import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Negated index of the smallest colour a candidate can take (c if none available), scaled by colours used."""
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(neighbor_colors.shape[0])
    avail = (neighbor_colors == 0)
    any_avail = avail.any(axis=1)
    first = np.where(any_avail, avail.argmax(axis=1), c)
    return -first / max(1, c)

