import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation urgency: distinct blocked colours divided by (free colours + 1), normalised by its max."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    sat = (neighbor_colors > 0).sum(axis=1).astype(float)
    free = (neighbor_colors == 0).sum(axis=1).astype(float)
    val = sat / (free + 1.0)
    return val / max(val.max(), 1e-9)

