import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Negated size of the largest colour class a candidate could join (0 if none), scaled by n."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    n = k + int(color_sizes.sum())
    joinable = (neighbor_colors == 0)
    sizes = np.where(joinable, color_sizes[None, :].astype(float), 0.0)
    largest = sizes.max(axis=1)
    return -largest / max(n, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Degree discounted by how many distinct colours already block the candidate's neighbourhood: degree / (1 + distinct blocked colours), normalised by its max."""
    degree = np.asarray(degree, dtype=float)
    k = degree.shape[0]
    if k == 0:
        return np.zeros(0)
    if neighbor_colors.shape[1] == 0:
        sat = np.zeros(k)
    else:
        sat = (neighbor_colors > 0).sum(axis=1).astype(float)
    val = degree / (1.0 + sat)
    denom = max(float(val.max()), 1e-9)
    return val / denom

