def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Uncoloured degree divided by (coloured degree + 1), normalised by its max."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    ud = adjacency.sum(axis=1).astype(float)
    cd = np.maximum(degree.astype(float) - ud, 0.0)
    r = ud / (cd + 1.0)
    return r / max(r.max(), 1e-12)

