def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation share times (1 - share of coloured vertices sitting in colours still free for the candidate)."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = neighbor_colors > 0                      # (k, c) colours already taken by a coloured neighbour
    sat = blocked.sum(axis=1).astype(float)            # distinct colours blocked per candidate
    sat_norm = sat / c
    total_coloured = float(color_sizes.sum())
    if total_coloured <= 0:
        return np.zeros(k)
    # per candidate: total size of colour classes that are NOT blocked
    free_sizes = (color_sizes[None, :] * (~blocked)).sum(axis=1).astype(float)
    free_room_share = free_sizes / max(total_coloured, 1.0)
    return sat_norm * (1.0 - free_room_share)

