def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation (distinct blocked colours / c) times (1 - largest free colour class share)."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = neighbor_colors > 0
    sat = blocked.sum(axis=1).astype(float)
    sat_norm = sat / c
    free = ~blocked
    has_free = free.any(axis=1)
    max_size = float(color_sizes.max()) if color_sizes.size > 0 else 0.0
    if max_size <= 0:
        return np.zeros(k)
    sizes = color_sizes.astype(float)
    masked = np.where(free, sizes[None, :], 0.0)
    best_free = masked.max(axis=1)
    best_free_share = np.where(has_free, best_free / max_size, 0.0)
    return sat_norm * (1.0 - best_free_share)

