def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Class-size-weighted count of coloured neighbours, normalised by total coloured vertices and by the max over candidates."""
    k = neighbor_colors.shape[0]
    if neighbor_colors.shape[1] == 0:
        return np.zeros(k)
    total_coloured = float(color_sizes.sum())
    raw = neighbor_colors @ color_sizes.astype(float)  # sum_col n[i,col] * size[col]
    ratio = raw / max(total_coloured, 1.0)
    m = ratio.max()
    if m <= 0:
        return np.zeros(k)
    return ratio / m

