def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Newest colour class fit minus mean fit to older classes: (s_new - nc_new)/s_new - mean_j<c-1 (s_j - nc_j)/s_j."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    nc = neighbor_colors.astype(float)
    s = color_sizes.astype(float)
    fit = (s[None, :] - nc) / np.maximum(s[None, :], 1.0)  # (k, c)
    if c == 1:
        return fit[:, 0]
    return fit[:, c - 1] - fit[:, :c - 1].mean(axis=1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation share (distinct colours among coloured neighbours / c) times cheapness (1 - first_free/c)."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        return np.zeros(k)
    blocked = (neighbor_colors > 0).sum(axis=1).astype(float) / c
    has_free = (neighbor_colors == 0)
    first_free = np.where(has_free.any(axis=1), has_free.argmax(axis=1), c).astype(float)
    return blocked * (1.0 - first_free / c)
